CREATE DATABASE IF NOT EXISTS fleetinventory CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fleetinventory;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','checker','mechanic') NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mechanics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,pin_hash VARCHAR(255) NOT NULL,employee_no VARCHAR(50),specialty VARCHAR(120),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE vehicles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,unit_no VARCHAR(50) UNIQUE NOT NULL,plate_no VARCHAR(30) UNIQUE NOT NULL,make VARCHAR(80),model VARCHAR(80),model_year SMALLINT,vin VARCHAR(100),engine_no VARCHAR(100),odometer DECIMAL(12,2) DEFAULT 0,status ENUM('active','maintenance','repair','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE task_master(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80) NOT NULL,task_name VARCHAR(160) NOT NULL,type ENUM('preventive','corrective','inspection') DEFAULT 'preventive',estimated_minutes INT DEFAULT 0,active TINYINT(1) DEFAULT 1);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(60) UNIQUE,name VARCHAR(160) NOT NULL,serialized TINYINT(1) DEFAULT 1,min_stock INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,serial_no VARCHAR(120) UNIQUE NOT NULL,status ENUM('available','issued','installed','returned','damaged','retired') DEFAULT 'available',cost DECIMAL(12,2) DEFAULT 0,current_vehicle_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(current_vehicle_id) REFERENCES vehicles(id));
CREATE TABLE job_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,jo_no VARCHAR(40) UNIQUE NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,checker_id BIGINT UNSIGNED NOT NULL,status ENUM('open','in_progress','for_approval','completed','on_hold','cancelled') DEFAULT 'open',complaint TEXT,opened_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),FOREIGN KEY(checker_id) REFERENCES users(id));
CREATE TABLE job_order_tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_order_id BIGINT UNSIGNED NOT NULL,task_id BIGINT UNSIGNED NOT NULL,mechanic_id BIGINT UNSIGNED NULL,status ENUM('pending','in_progress','completed') DEFAULT 'pending',completed_at DATETIME NULL,pin_verified_at DATETIME NULL,FOREIGN KEY(job_order_id) REFERENCES job_orders(id),FOREIGN KEY(task_id) REFERENCES task_master(id),FOREIGN KEY(mechanic_id) REFERENCES mechanics(id));
CREATE TABLE part_issues(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_order_id BIGINT UNSIGNED NOT NULL,job_order_task_id BIGINT UNSIGNED NULL,product_unit_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,installed_at DATETIME NULL,removed_at DATETIME NULL,removal_reason VARCHAR(255),FOREIGN KEY(job_order_id) REFERENCES job_orders(id),FOREIGN KEY(job_order_task_id) REFERENCES job_order_tasks(id),FOREIGN KEY(product_unit_id) REFERENCES product_units(id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
CREATE TABLE outside_purchases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_order_id BIGINT UNSIGNED NOT NULL,job_order_task_id BIGINT UNSIGNED NULL,item_name VARCHAR(160) NOT NULL,qty DECIMAL(10,2) DEFAULT 1,unit_price DECIMAL(12,2) DEFAULT 0,supplier VARCHAR(160),receipt_no VARCHAR(100),serial_no VARCHAR(120),purchase_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_order_id) REFERENCES job_orders(id),FOREIGN KEY(job_order_task_id) REFERENCES job_order_tasks(id));
CREATE TABLE purchase_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,outside_purchase_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(outside_purchase_id) REFERENCES outside_purchases(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
